package com.example.cvd;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.CompletableFuture;

@EnabledIfEnvironmentVariable(named="CVD_EMAIL_TEST_DB",matches="jdbc:postgresql://localhost:15439/email_test")
class MetrologyDatabaseTest {
 JdbcTemplate pg;DataStore db;AccessStore access;MetrologyApi api;Pipeline pipeline;KafkaTemplate<String,String> kafka;ObjectMapper mapper=new ObjectMapper();AccessSessions.Identity leader;
 @BeforeEach void setup()throws Exception{var ds=new DriverManagerDataSource(System.getenv("CVD_EMAIL_TEST_DB"),"cvd","email-test");pg=new JdbcTemplate(ds);pg.execute("DROP SCHEMA public CASCADE;CREATE SCHEMA public;CREATE TABLE auth_bootstrap(id integer PRIMARY KEY);INSERT INTO auth_bootstrap VALUES(1)");access=new AccessStore(pg,new DataSourceTransactionManager(ds),"");access.initialize();pg.execute("CREATE TABLE commands(id text primary key,equipment_id text,body jsonb,status text)");db=new DataStore(pg,mapper,System.getenv("CVD_EMAIL_TEST_DB"),"cvd","email-test");pipeline=mock(Pipeline.class);kafka=mock(KafkaTemplate.class);api=new MetrologyApi(db,pipeline,access,kafka,true);api.init();leader=new AccessSessions.Identity(UUID.randomUUID().toString(),"fixture","Leader","EE",1);pg.update("INSERT INTO app_users(id,username,password_hash,role,department) VALUES(?::uuid,'fixture','unused','Leader','EE')",leader.id());actor(leader);}
 @AfterEach void close(){SecurityContextHolder.clearContext();((com.zaxxer.hikari.HikariDataSource)db.ts.getDataSource()).close();}
 void actor(AccessSessions.Identity u){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,List.of()));}
 ObjectNode event(boolean complete,String eq,String wafer,String run){var n=mapper.createObjectNode().put("equipmentId",eq).put("waferId",wafer).put("lotId","l1").put("sourceTime",Instant.now().plusSeconds(1).toString()).put("kind",complete?"process-result":"movement-complete");var p=n.putObject("payload").put("processRunId",run).put("slot",1).put("purpose","product").put("pm","PM1");if(complete){p.put("complete",true);var s=new MetrologyValidationTest().result().path("source").deepCopy();((ObjectNode)s).put("equipmentId",eq).put("waferId",wafer).put("processRunId",run);p.set("result",s);}else p.put("result","success").put("to","LP1");return n;}
 String create(String eq,String wafer,String run){api.evidence(event(true,eq,wafer,run).toString());api.evidence(event(false,eq,wafer,run).toString());return pg.queryForObject("SELECT id FROM metrology_runs WHERE source_key=?",String.class,MetrologyApi.key(eq,wafer,run));}
 long count(){return pg.queryForObject("SELECT count(*) FROM metrology_runs",Long.class);}
 ObjectNode result(String id,long seq,boolean review){var n=mapper.createObjectNode().put("equipmentId",MetrologyApi.STATION).put("eventId","event-"+id+"-"+seq).put("sequence",seq).put("kind","measurement-state");var p=n.putObject("payload").put("measurementId",id).put("state","completed");var r=new MetrologyValidationTest().result();r.set("source",api.detail(id).path("source"));if(review){r.put("defectQuality","review").put("quality","review");r.withArray("defects").addObject().put("defectId","d1").put("type","particle").put("x",0).put("y",0).put("sizeUm",2);}p.set("result",r);return n;}
 @Test void migrationEvidenceAndExclusions()throws Exception{api.init();var done=event(true,Equipment.FIRST,"w1","run1");var returned=event(false,Equipment.FIRST,"w1","run1");api.evidence(returned.toString());assertEquals(0,count());api.evidence(done.toString());api.evidence(done.toString());api.evidence(returned.toString());assertEquals(1,count());create(Equipment.IDS.get(1),"w1","run1");assertEquals(2,count());var old=event(true,Equipment.FIRST,"old","oldrun").put("sourceTime","2020-01-01T00:00:00Z");api.evidence(old.toString());api.evidence(event(false,Equipment.FIRST,"old","oldrun").toString());assertEquals(2,count());api.evidence(event(true,Equipment.FIRST,"held","recovery/execution").toString());assertEquals(2,count());var scrap=event(false,Equipment.FIRST,"held","recovery/execution");((ObjectNode)scrap.get("payload")).put("result","scrap");api.evidence(scrap.toString());assertEquals(2,count());var ret=event(false,Equipment.FIRST,"held","recovery/execution");api.evidence(ret.toString());assertEquals(3,count());}
 @Test void resultAtomicityRemeasureAndNoSideEffects(){String id=create(Equipment.FIRST,"w1","run1");var result=result(id,3,true);api.result(result.toString());api.result(result.toString());assertEquals(1,pg.queryForObject("SELECT count(*) FROM metrology_inbox",Integer.class));assertTrue(api.detail(id).path("alarm").asBoolean());String immutable=api.detail(id).path("result").toString();var request=Map.of("requestId",UUID.randomUUID().toString());String next=api.remeasure(id,request).get("id");assertEquals(next,api.remeasure(id,request).get("id"));assertEquals(2,count());assertEquals(immutable,api.detail(id).path("result").toString());actor(new AccessSessions.Identity(leader.id(),"fixture","Operator","EE",1));assertThrows(Exception.class,()->api.remeasure(id,Map.of("requestId",UUID.randomUUID().toString())));assertThrows(Exception.class,()->api.acknowledge(id));verifyNoInteractions(kafka,pipeline);actor(leader);api.acknowledge(id);assertTrue(api.detail(id).path("acknowledged").asBoolean());}
 @Test void invalidResultAndRetention(){String id=create(Equipment.FIRST,"w1","run1");var bad=result(id,1,false);((ObjectNode)bad.path("payload").path("result")).remove("defects");api.result(bad.toString());assertEquals("awaiting-remeasure",api.detail(id).path("state").asText());assertTrue(api.detail(id).path("result").isNull());String next=api.remeasure(id,Map.of("requestId",UUID.randomUUID().toString())).get("id");api.result(result(next,2,true).toString());pg.update("UPDATE metrology_runs SET completed_at=now()-interval '31 days' WHERE id=?",next);api.cleanup();assertFalse(api.detail(next).path("expired").asBoolean());api.acknowledge(next);api.cleanup();assertTrue(api.detail(next).path("expired").asBoolean());assertThrows(Exception.class,()->api.remeasure(next,Map.of("requestId",UUID.randomUUID().toString())));}
 @Test void fifoDispatchRetryAndDisabled()throws Exception{String first=create(Equipment.FIRST,"w1","run1");create(Equipment.IDS.get(1),"w2","run2");pg.update("UPDATE metrology_runs SET arrival_at=now()-interval '5 seconds'");when(pipeline.signControl(anyString())).thenAnswer(i->i.getArgument(0));when(kafka.send(eq("cvd.commands.v1"),eq(MetrologyApi.STATION),anyString())).thenReturn(CompletableFuture.completedFuture(null));api.dispatch();api.dispatch();verify(kafka,times(1)).send(eq("cvd.commands.v1"),eq(MetrologyApi.STATION),contains(first));pg.update("UPDATE metrology_runs SET last_sent=now()-interval '20 seconds' WHERE id=?",first);api.dispatch();verify(kafka,times(2)).send(eq("cvd.commands.v1"),eq(MetrologyApi.STATION),contains(first));var off=new MetrologyApi(db,pipeline,access,kafka,false);off.init();off.dispatch();off.evidence(event(true,Equipment.FIRST,"off","off").toString());assertEquals(2,count());}

 @Test void dummyIncompleteAndActiveRetention(){var e=event(true,Equipment.FIRST,"dummy","dummy-run");((ObjectNode)e.path("payload")).put("purpose","dummy");api.evidence(e.toString());api.evidence(event(false,Equipment.FIRST,"dummy","dummy-run").toString());String id=pg.queryForObject("SELECT id FROM metrology_runs",String.class);assertEquals("dummy",api.detail(id).path("source").path("purpose").asText());var incomplete=event(true,Equipment.FIRST,"partial","partial-run");((ObjectNode)incomplete.path("payload")).put("complete",false);api.evidence(incomplete.toString());api.evidence(event(false,Equipment.FIRST,"partial","partial-run").toString());assertEquals(1,count());api.result(result(id,1,false).toString());String next=api.remeasure(id,Map.of("requestId",UUID.randomUUID().toString())).get("id");pg.update("UPDATE metrology_runs SET completed_at=now()-interval '31 days' WHERE id=?",id);api.cleanup();assertFalse(api.detail(id).path("expired").asBoolean());pg.update("UPDATE metrology_runs SET state='awaiting-remeasure' WHERE id=?",next);api.cleanup();assertTrue(api.detail(id).path("expired").asBoolean());}
 @Test void sourceMissingDataFailsExplicitly(){var e=event(true,Equipment.FIRST,"missing","missing-run");((ObjectNode)e.path("payload").path("result")).remove("sampleThicknessNm");api.evidence(e.toString());api.evidence(event(false,Equipment.FIRST,"missing","missing-run").toString());String id=pg.queryForObject("SELECT id FROM metrology_runs",String.class);assertEquals("awaiting-remeasure",api.detail(id).path("state").asText());assertEquals("invalid-source",api.detail(id).path("failure_reason").asText());assertThrows(Exception.class,()->api.remeasure(id,Map.of("requestId",UUID.randomUUID().toString())));}
}
